const SISTEMA = "Você escreve em nome de Eduardo Cardoso, em português do Brasil.\n\nQUEM É O EDUARDO (use só estes fatos, nunca invente outros):\n- Mora em Chapecó/SC. Experiência real em suporte técnico (Help Desk) e em automação de processos com n8n, APIs e LLMs.\n- Faz pós-graduação em IA, com foco em agentes.\n- Projetos reais: Mentor de Gestão Industrial (multiagente com CrewAI, RAG com ChromaDB, Streamlit, demo no Hugging Face); replicador de promoções de Pokémon TCG para WhatsApp (Node.js/TypeScript, rodando 24/7 numa VPS com Coolify e painel próprio); PC Dashboard (app desktop em Tauri/Rust); conversor de unidades (React/TypeScript); este próprio copiloto de LinkedIn em n8n.\n- Busca trabalho remoto em automação/IA, suporte técnico ou suporte a produto de IA. Nunca escreva \"busco vaga\", \"open to work\" ou similar no texto.\n\nVOZ:\n- Pragmático, de colega para colega. Direto, técnico sem ser pedante, honesto sobre erros e limites.\n- Nada de palco, motivacional ou autopromoção vazia.\n\nPROIBIDO:\n- Travessão longo (—) ou meia-risca (–). Use vírgula, ponto ou parênteses.\n- Mais de 1 emoji no texto inteiro. Emojis 🚀🔥💡👏📌👇🎯 nunca.\n- Listas com marcadores transformando o texto em slide. Prefira parágrafos curtos.\n- Aberturas clichê: \"No mundo acelerado...\", \"Você já parou para pensar...\", \"Recentemente me deparei...\", \"No cenário atual...\".\n- Fechamentos pedindo engajamento: \"E você, o que acha? Comenta aí\", \"Compartilhe\", \"Salve este post\".\n- Palavras: disruptivo, mindset, ecossistema, revolucionar, game changer, sinergia, fora da caixa, jornada.\n- Números, clientes, resultados ou experiências que não estejam nos fatos acima ou na ideia enviada.\n- Inventar acontecimentos: \"a primeira versão\", \"no teste deu errado\", \"um cliente pediu\", bugs, conversas ou aprendizados que a ideia não contou. Se faltar um detalhe concreto, escreva de forma geral ou deixe um marcador entre colchetes, ex.: [conte aqui o erro que aconteceu], para o Eduardo completar.\n";
function llmBody(userContent, temperature, maxTokens) {
  return {
    model: $env.LLM_MODEL || 'deepseek-v4.1-flash',
    temperature,
    max_tokens: maxTokens,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: SISTEMA },
      { role: 'user', content: userContent },
    ],
  };
}

const P_POST = "Escreva duas versões de post para o LinkedIn a partir da ideia abaixo.\n\nVersão 1 (Bastidores): narrativa curta de algo que aconteceu na prática, a dor real e o que ele aprendeu.\nVersão 2 (Arquitetura): foco técnico, comparando o jeito frágil com o jeito robusto de resolver.\n\nRegras de formato para as duas:\n- 900 a 1.500 caracteres.\n- Primeira linha é um gancho seco, uma afirmação forte ou o problema direto.\n- Parágrafos de 1 a 3 linhas separados por linha em branco (leitura no celular).\n- Termina com uma constatação honesta de engenharia ou uma pergunta natural entre profissionais, sem pedir engajamento.\n- No máximo 3 hashtags no final, relevantes (ex.: #n8n #automacao #IA).\n\nTambém gere um prompt de imagem em inglês técnico para o Meta AI: infográfico ou diagrama em dark mode (#0f172a), 16:9, com todos os textos da imagem em português entre aspas, sem robôs, sem vidro 3D, sem esferas brilhantes, sem textos em inglês.\n\nResponda SOMENTE com JSON válido neste formato:\n{\"v1\": \"texto da versão 1\", \"v2\": \"texto da versão 2\", \"imagem\": \"prompt da imagem\"}\n\nIDEIA:\n";
const P_COMENT = "Abaixo está o texto de um post do LinkedIn de outra pessoa. Escreva dois comentários que o Eduardo poderia publicar nele.\n\nComentário 1: acrescenta um ponto técnico ou prático que o post não disse, ligado à experiência real dele quando fizer sentido.\nComentário 2: faz uma pergunta específica e inteligente sobre o conteúdo, que puxe conversa com o autor.\n\nRegras:\n- 2 a 4 frases cada. Nada de \"Ótimo post!\", \"Parabéns pela reflexão\", \"Concordo totalmente\".\n- Não elogie o autor de forma genérica, não se promova, não peça conexão.\n- Escreva no mesmo idioma do post.\n- Se o post for vago demais para comentar algo útil, diga isso no campo \"aviso\" e ainda assim sugira os comentários.\n\nResponda SOMENTE com JSON válido neste formato:\n{\"c1\": \"comentário 1\", \"c2\": \"comentário 2\", \"aviso\": \"\"}\n\nPOST:\n";
const P_CAND = "O Eduardo quer se candidatar à vaga abaixo. Prepare o material para ele.\n\n1. \"nota_recrutador\": mensagem para mandar ao recrutador ou junto do convite de conexão no LinkedIn. Máximo 280 caracteres. Cita a vaga, conecta UM fato real do perfil com a vaga, termina com algo simples como pedir para conversar. Sem bajulação, sem \"venho por meio desta\".\n2. \"destaques\": 3 pontos reais do perfil dele que mais combinam com esta vaga (use só os fatos conhecidos).\n3. \"lacunas\": até 2 requisitos da vaga que ele não comprova hoje, e uma frase honesta de como tratar cada um na entrevista.\n4. \"palavras_chave\": até 6 termos da vaga que vale ter no currículo e no perfil do LinkedIn, se forem verdade.\n\nResponda SOMENTE com JSON válido:\n{\"nota_recrutador\": \"...\", \"destaques\": [\"...\", \"...\", \"...\"], \"lacunas\": [\"...\"], \"palavras_chave\": [\"...\"]}\n\nVAGA:\n";
const AJUDA = "Copiloto LinkedIn\n\n/post <ideia>  gera 2 versoes de post + prompt de imagem\n/comentar <texto do post>  sugere 2 comentarios (ou so cola o texto)\n/vagas  roda o radar de vagas remotas agora\n/pipeline  lista as vagas que voce marcou como Quero\n/status  confere se esta tudo de pe\n\nO radar roda sozinho as 9h e as 15h e so te chama quando acha vaga com nota 70+.\nNada e publicado sozinho: voce copia, ajusta e posta.";

const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};

const secret = $env.TG_WEBHOOK_SECRET;
if (secret && headers['x-telegram-bot-api-secret-token'] !== secret) return [];

const sd = $getWorkflowStaticData('global');
sd.jobs = sd.jobs || {};
sd.pipeline = sd.pipeline || {};

const cq = body.callback_query;
const msg = body.message || body.edited_message || (cq && cq.message);
if (!msg || !msg.chat) return [];
const chatId = String(msg.chat.id);
if (chatId !== String($env.TELEGRAM_CHAT_ID)) return [];

const simples = (text) => [{ json: { chatId, route: 'simples', text } }];
const llm = (kind, ack, userContent, temperature = 0.8) => [{ json: {
  chatId, route: 'llm', kind, ack,
  session: 'copiloto-' + chatId + '-' + kind,
  llmBody: llmBody(userContent, temperature, 3000),
} }];

if (cq) {
  const [tipo, id] = String(cq.data || '').split(':');
  const job = sd.jobs[id];
  if (!job) return simples('Nao achei essa vaga na memoria (pode ser antiga). Abre pelo botao do link.');
  const agora = new Date().toISOString();
  if (tipo === 'x') {
    sd.pipeline[id] = { status: 'ignorada', at: agora, title: job.title };
    return simples('Ignorada: ' + job.title);
  }
  if (tipo === 'q') {
    sd.pipeline[id] = { status: 'quero', at: agora, title: job.title, empresa: job.empresa, link: job.link };
    const vaga = 'Titulo: ' + job.title + '\nEmpresa: ' + job.empresa + '\n\n' + job.desc;
    return llm('candidatura', 'Anotado no pipeline. Preparando mensagem para o recrutador...', P_CAND + vaga, 0.6);
  }
  return [];
}

const text = (msg.text || msg.caption || '').trim();
if (!text) return simples('Por enquanto eu so entendo texto. Manda /menu para ver os comandos.');

const m = text.match(/^\/(\w+)(?:@\w+)?\s*([\s\S]*)$/);
const cmd = m ? m[1].toLowerCase() : null;
const arg = m ? m[2].trim() : text;

if (cmd === 'start' || cmd === 'menu' || cmd === 'ajuda' || cmd === 'help') return simples(AJUDA);
if (cmd === 'status') {
  const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  const vistas = Object.keys(sd.seen || {}).length;
  const quero = Object.values(sd.pipeline).filter((p) => p.status === 'quero').length;
  return simples('No ar.\nModelo: ' + ($env.LLM_MODEL || '?') + '\nHora do servidor: ' + agora +
    '\nVagas ja analisadas: ' + vistas + '\nNo pipeline (Quero): ' + quero);
}
if (cmd === 'vagas' || cmd === 'radar') {
  return [{ json: { chatId, route: 'radar', ack: 'Buscando vagas remotas novas no Remotar e dando nota. Leva uns 30 a 60 segundos...' } }];
}
if (cmd === 'pipeline') {
  const itens = Object.entries(sd.pipeline)
    .filter(([, p]) => p.status === 'quero')
    .sort((a, b) => (a[1].at < b[1].at ? 1 : -1))
    .slice(0, 20);
  if (!itens.length) return simples('Pipeline vazio. Quando o radar mandar uma vaga, toque em Quero.');
  const linhas = itens.map(([, p], i) => (i + 1) + '. ' + p.title + ' · ' + (p.empresa || '') +
    '\n   marcada em ' + new Date(p.at).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }) + '\n   ' + (p.link || ''));
  return simples('Vagas marcadas como Quero:\n\n' + linhas.join('\n\n'));
}
if (cmd === 'post') {
  if (!arg) return simples('Manda a ideia junto. Ex.: /post o dia em que meu agente de IA estourou o limite da API e como eu resolvi com fila');
  return llm('post', 'Escrevendo 2 versoes do post...', P_POST + arg);
}
if (cmd === 'comentar') {
  if (!arg) return simples('Cola o texto do post depois do comando, ou so cola o texto direto sem comando.');
  return llm('comentario', 'Lendo o post e pensando nos comentarios...', P_COMENT + arg);
}
if (cmd) return simples('Comando desconhecido. /menu mostra o que eu sei fazer.');
if (/linkedin\.com|lnkd\.in/i.test(text) && text.length < 300) {
  return simples('Eu nao abro links do LinkedIn (para proteger sua conta). Copia o texto do post no app e cola aqui.');
}
if (text.length < 40) return simples('Nao entendi. Para comentar um post, cola o texto inteiro dele. /menu mostra os comandos.');
return llm('comentario', 'Lendo o post e pensando nos comentarios...', P_COMENT + text);

const ctx = $('Roteador').first().json;
const resp = $input.first().json;
const chatId = ctx.chatId;

function limpa(s) {
  return String(s || '').replace(/\s*[—–]\s*/g, ', ').replace(/, ,/g, ',').trim();
}
const lista = (arr) => (Array.isArray(arr) ? arr : [arr]).filter(Boolean).map((x) => '• ' + limpa(x)).join('\n');

let raw = '';
try { raw = resp.choices[0].message.content || ''; } catch (e) { raw = ''; }
if (!raw) {
  const erro = resp.error ? (resp.error.message || JSON.stringify(resp.error)) : 'resposta vazia';
  return [{ json: { chatId, text: 'A IA nao respondeu: ' + erro } }];
}
let data;
try {
  data = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, ''));
} catch (e) {
  return [{ json: { chatId, text: 'Resposta fora do formato, segue crua:\n\n' + limpa(raw).slice(0, 3800) } }];
}

const out = [];
const add = (text) => out.push({ json: { chatId, text } });
if (ctx.kind === 'post') {
  const v1 = limpa(data.v1), v2 = limpa(data.v2);
  add('VERSAO 1 · Bastidores (' + v1.length + ' caracteres)\n\n' + v1);
  add('VERSAO 2 · Arquitetura (' + v2.length + ' caracteres)\n\n' + v2);
  if (data.imagem) add('Prompt de imagem (Meta AI):\n\n' + String(data.imagem).trim());
} else if (ctx.kind === 'candidatura') {
  add('MENSAGEM PARA O RECRUTADOR\n\n' + limpa(data.nota_recrutador));
  add('O QUE DESTACAR\n' + lista(data.destaques) +
      '\n\nLACUNAS E COMO TRATAR\n' + lista(data.lacunas) +
      '\n\nPALAVRAS-CHAVE (so se forem verdade)\n' + (data.palavras_chave || []).join(', '));
} else {
  if (data.aviso) add('Aviso: ' + limpa(data.aviso));
  add('COMENTARIO 1\n\n' + limpa(data.c1));
  add('COMENTARIO 2\n\n' + limpa(data.c2));
}
return out;

const TERMOS = ["n8n", "automação", "automacao", "inteligência artificial", "agentes de IA", "suporte técnico", "help desk", "service desk", "integrações", "customer success"];
let manual = false;
let chatId = String($env.TELEGRAM_CHAT_ID);
try {
  const r = $('Roteador').first().json;
  if (r && r.route === 'radar') { manual = true; chatId = r.chatId; }
} catch (e) { /* disparo pela agenda */ }
return TERMOS.map((t) => ({ json: {
  manual, chatId,
  url: 'https://api.remotar.com.br/jobs?search=' + encodeURIComponent(t) + '&page=1',
} }));

const SISTEMA = "Você escreve em nome de Eduardo Cardoso, em português do Brasil.\n\nQUEM É O EDUARDO (use só estes fatos, nunca invente outros):\n- Mora em Chapecó/SC. Experiência real em suporte técnico (Help Desk) e em automação de processos com n8n, APIs e LLMs.\n- Faz pós-graduação em IA, com foco em agentes.\n- Projetos reais: Mentor de Gestão Industrial (multiagente com CrewAI, RAG com ChromaDB, Streamlit, demo no Hugging Face); replicador de promoções de Pokémon TCG para WhatsApp (Node.js/TypeScript, rodando 24/7 numa VPS com Coolify e painel próprio); PC Dashboard (app desktop em Tauri/Rust); conversor de unidades (React/TypeScript); este próprio copiloto de LinkedIn em n8n.\n- Busca trabalho remoto em automação/IA, suporte técnico ou suporte a produto de IA. Nunca escreva \"busco vaga\", \"open to work\" ou similar no texto.\n\nVOZ:\n- Pragmático, de colega para colega. Direto, técnico sem ser pedante, honesto sobre erros e limites.\n- Nada de palco, motivacional ou autopromoção vazia.\n\nPROIBIDO:\n- Travessão longo (—) ou meia-risca (–). Use vírgula, ponto ou parênteses.\n- Mais de 1 emoji no texto inteiro. Emojis 🚀🔥💡👏📌👇🎯 nunca.\n- Listas com marcadores transformando o texto em slide. Prefira parágrafos curtos.\n- Aberturas clichê: \"No mundo acelerado...\", \"Você já parou para pensar...\", \"Recentemente me deparei...\", \"No cenário atual...\".\n- Fechamentos pedindo engajamento: \"E você, o que acha? Comenta aí\", \"Compartilhe\", \"Salve este post\".\n- Palavras: disruptivo, mindset, ecossistema, revolucionar, game changer, sinergia, fora da caixa, jornada.\n- Números, clientes, resultados ou experiências que não estejam nos fatos acima ou na ideia enviada.\n- Inventar acontecimentos: \"a primeira versão\", \"no teste deu errado\", \"um cliente pediu\", bugs, conversas ou aprendizados que a ideia não contou. Se faltar um detalhe concreto, escreva de forma geral ou deixe um marcador entre colchetes, ex.: [conte aqui o erro que aconteceu], para o Eduardo completar.\n";
function llmBody(userContent, temperature, maxTokens) {
  return {
    model: $env.LLM_MODEL || 'deepseek-v4.1-flash',
    temperature,
    max_tokens: maxTokens,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: SISTEMA },
      { role: 'user', content: userContent },
    ],
  };
}

const P_RADAR = "Avalie o encaixe de cada vaga abaixo com o perfil do Eduardo e dê uma nota de 0 a 100.\n\nO que ele procura (nota alta):\n- Trabalho 100% remoto.\n- Nível júnior ou pleno.\n- Automação de processos, n8n, integrações com APIs, agentes de IA, LLMs, RPA leve.\n- Suporte técnico, Help Desk, service desk N1/N2, suporte a sistemas/SaaS.\n- Suporte, implantação ou operação de produto de IA (AI ops, onboarding técnico, customer success técnico).\n\nO que derruba a nota:\n- Exige nível sênior, especialista ou liderança como requisito.\n- Vendas, marketing, jurídico, financeiro, RH ou área sem relação com tecnologia.\n- Desenvolvimento pesado em stack que ele não mostra (ex.: Java/.NET sênior, mobile nativo, SRE sênior).\n- Inglês fluente obrigatório: desconte um pouco, não zere.\n\nEscala: 85+ encaixe forte; 70 a 84 vale aplicar; 50 a 69 fraco; abaixo de 50 não combina.\n\nPara cada vaga, \"motivo\" tem no máximo 140 caracteres e diz o porquê da nota de forma concreta.\n\nResponda SOMENTE com JSON válido:\n{\"vagas\": [{\"id\": \"id da vaga\", \"nota\": 0, \"motivo\": \"...\"}]}\n\nVAGAS:\n";
const ctx = $('Radar: buscas').first().json;
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
sd.jobs = sd.jobs || {};

const agora = Date.now();
const DIA = 86400000;
for (const [id, t] of Object.entries(sd.seen)) if (agora - t > 45 * DIA) delete sd.seen[id];

const POS = ['n8n', 'automa', 'integra', 'api', 'agente', ' ia ', 'ia generativa', 'inteligência artificial',
  'inteligencia artificial', 'llm', 'chatbot', 'rpa', 'suporte', 'help desk', 'helpdesk', 'service desk',
  'implanta', 'onboarding', 'customer success', 'no-code', 'low-code', 'python', 'zapier', 'make.com', 'sistemas'];
const NEG_TITULO = ['sênior', 'senior', 'sr ', 'sr.', 'especialista', 'lead', 'head', 'gerente', 'diretor',
  'coordenador', 'vendas', 'sales', 'advogad', 'jurídic', 'contábil', 'account executive', 'sdr', 'bdr', 'manager',
  'híbrido', 'hibrido', 'hybrid', 'presencial', 'principal', 'staff', 'líder', 'lider'];

const semHtml = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim();

const porId = {};
for (const item of $input.all()) {
  for (const j of (item.json && item.json.data) || []) porId[String(j.id)] = j;
}

const candidatas = [];
for (const [id, j] of Object.entries(porId)) {
  if (sd.seen[id]) continue;
  if (j.active === false || j.expired === true) continue;
  const criada = Date.parse(j.createdAt || '');
  if (!criada || agora - criada > 4 * DIA) continue;
  const titulo = String(j.title || '').toLowerCase();
  const texto = ' ' + (titulo + ' ' + (j.subtitle || '') + ' ' + semHtml(j.description)).toLowerCase() + ' ';
  const score = POS.reduce((n, k) => n + (texto.includes(k) ? 1 : 0), 0);
  if (score <= 0 || NEG_TITULO.some((k) => (' ' + titulo + ' ').includes(k))) { sd.seen[id] = agora; continue; }
  candidatas.push({ id, score, j, criada });
}
candidatas.sort((a, b) => b.score - a.score);
const lote = candidatas.slice(0, 25);

for (const c of lote) {
  sd.jobs[c.id] = {
    id: c.id,
    title: c.j.title,
    empresa: (c.j.company && c.j.company.name) || '',
    link: c.j.externalLink || ('https://remotar.com.br/job/' + c.id),
    desc: semHtml((c.j.subtitle || '') + ' ' + c.j.description).slice(0, 2500),
    created: c.criada,
  };
}
const ids = Object.keys(sd.jobs).sort((a, b) => sd.jobs[b].created - sd.jobs[a].created);
for (const id of ids.slice(400)) delete sd.jobs[id];

if (!lote.length) {
  if (!ctx.manual) return [];
  return [{ json: { chatId: ctx.chatId, temVagas: false, text: 'Radar: nenhuma vaga nova relevante desde a ultima busca.' } }];
}

const vagas = lote.map((c) => ({
  id: c.id,
  titulo: c.j.title,
  empresa: sd.jobs[c.id].empresa,
  descricao: sd.jobs[c.id].desc.slice(0, 700),
}));
return [{ json: {
  chatId: ctx.chatId,
  manual: ctx.manual,
  temVagas: true,
  ids: lote.map((c) => c.id),
  llmBody: llmBody(P_RADAR + JSON.stringify(vagas), 0.2, 4000),
} }];

const ctx = $('Radar: filtrar').first().json;
const resp = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const chatId = ctx.chatId;

let raw = '';
try { raw = resp.choices[0].message.content || ''; } catch (e) { raw = ''; }
let data = null;
try { data = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '')); } catch (e) { data = null; }
if (!data || !Array.isArray(data.vagas)) {
  const erro = resp.error ? (resp.error.message || JSON.stringify(resp.error)) : 'resposta fora do formato';
  return [{ json: { chatId, text: 'Radar: a IA falhou ao dar nota (' + erro + '). Tento de novo na proxima rodada.' } }];
}

const notas = {};
for (const v of data.vagas) notas[String(v.id)] = v;
const agora = Date.now();
for (const id of ctx.ids) sd.seen[id] = agora;

const boas = ctx.ids
  .map((id) => ({ id, job: sd.jobs[id], nota: Number((notas[id] || {}).nota || 0), motivo: (notas[id] || {}).motivo || '' }))
  .filter((v) => v.job && v.nota >= 70)
  .sort((a, b) => b.nota - a.nota)
  .slice(0, 8);

if (!boas.length && !ctx.manual) return [];

const out = [{ json: { chatId, text: 'Radar: ' + ctx.ids.length + ' vagas novas analisadas, ' + boas.length + ' com nota 70 ou mais.' } }];
for (const v of boas) {
  const data = new Date(v.job.created).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  out.push({ json: {
    chatId,
    text: v.nota + '/100 · ' + v.job.title + '\n' + v.job.empresa + ' · publicada em ' + data + '\n\n' + v.motivo,
    reply_markup: { inline_keyboard: [
      [{ text: 'Quero', callback_data: 'q:' + v.id }, { text: 'Ignorar', callback_data: 'x:' + v.id }],
      [{ text: 'Abrir vaga', url: v.job.link }],
    ] },
  } });
}
return out;
